insert into leaving_reasons (flywheel_driver, flywheel_subdriver, flywheel_type, title, body, sources) values ('Price and discounts', 'Fees', null, 'Hidden Fees at Checkout', E'Customers are significantly frustrated that fees — including service, delivery, and bag fees — often aren''t visible until checkout, which inflates the final cost unexpectedly [1].\nThis lack of upfront transparency causes many to abandon their baskets after investing time selecting their order [6].\nCustomers want to see delivery and service fees displayed on the restaurant page before they start ordering [1].', '[{"label":"1","url":"https://docs.google.com/presentation/d/1K0ti5vGuWNgv9O24LYv7NnYnI2EjJZrFKf5g8nWrrgQ/edit#slide=id.g384deac8ba0_3_1417"},{"label":"6","url":"https://docs.google.com/presentation/d/1K0ti5vGuWNgv9O24LYv7NnYnI2EjJZrFKf5g8nWrrgQ/edit#slide=id.g384deac8ba0_3_1302"}]'::jsonb);
insert into leaving_reasons (flywheel_driver, flywheel_subdriver, flywheel_type, title, body, sources) values ('Price and discounts', 'Fees', null, 'Lack of Fee Understanding & Transparency', E'There''s confusion around what fees actually cover, particularly service fees [2].\nFee transparency is highly important to customers, especially in the UK, where almost 60% prefer seeing a detailed breakdown of individual fees rather than an aggregated total [7].\nJET currently ranks 3rd out of 6 major platforms for customer satisfaction with understanding costs and fees at 84.3% [3].', '[{"label":"2","url":"https://docs.google.com/presentation/d/19q8wn03kvBwmVj6ZjO6Erlob7gDyzbGv2LZr5kQFbE0/edit#slide=id.g323c85467e2_0_16"},{"label":"7","url":"https://docs.google.com/presentation/d/19q8wn03kvBwmVj6ZjO6Erlob7gDyzbGv2LZr5kQFbE0/edit#slide=id.g3248d501297_0_9"},{"label":"3","url":"https://docs.google.com/presentation/d/1BCjb4YDZpulBv812xE97Rk8psluBVQUBexBqvb7YcZk/edit#slide=id.g2f5784c38e5_0_1520"}]'::jsonb);
insert into leaving_reasons (flywheel_driver, flywheel_subdriver, flywheel_type, title, body, sources) values ('Price and discounts', 'Fees', null, 'Perceived Double-Charging', E'Many customers feel they''re being charged twice — once through inflated menu prices (to cover restaurant commissions) and again through service fees [1].\nThis perception of unjustified charges is pushing some customers to order directly from restaurants instead [1].', '[{"label":"1","url":"https://docs.google.com/presentation/d/1K0ti5vGuWNgv9O24LYv7NnYnI2EjJZrFKf5g8nWrrgQ/edit#slide=id.g384deac8ba0_3_1417"}]'::jsonb);
insert into leaving_reasons (flywheel_driver, flywheel_subdriver, flywheel_type, title, body, sources) values ('Price and discounts', 'Fees', null, 'Industry-Wide Decline in Satisfaction', E'Satisfaction with fee transparency has dropped across all platforms year-over-year.\nJET saw a 5% decline from 84% (2024) to 79% (2025) [6].\nCustomers view the cumulative fees as excessive and exploitative, leading some to reduce usage or seek alternatives [1].', '[{"label":"6","url":"https://docs.google.com/presentation/d/1K0ti5vGuWNgv9O24LYv7NnYnI2EjJZrFKf5g8nWrrgQ/edit#slide=id.g384deac8ba0_3_1302"},{"label":"1","url":"https://docs.google.com/presentation/d/1K0ti5vGuWNgv9O24LYv7NnYnI2EjJZrFKf5g8nWrrgQ/edit#slide=id.g384deac8ba0_3_1417"}]'::jsonb);
insert into leaving_reasons (flywheel_driver, flywheel_subdriver, flywheel_type, title, body, sources) values ('Price and discounts', 'Fees', null, 'Payment Fee Frustration', E'Customers are also frustrated with payment fees specifically, similar to their frustration with other fee types [4].', '[{"label":"4","url":"https://docs.google.com/presentation/d/19q8wn03kvBwmVj6ZjO6Erlob7gDyzbGv2LZr5kQFbE0/edit#slide=id.g3230e42ceee_0_574"}]'::jsonb);
